import { get, prepareMutation } from './api-client.js';

const TABS = [['jobs','生产任务'],['inventory','材料库存'],['profiles','工艺模板'],['services','服务连接']];
const MATERIALS = {PLA:'PLA',PETG:'PETG',ABS:'ABS',RESIN:'树脂',ALUMINUM:'铝合金',CNC:'CNC 材料'};
const STATUS = {QUEUED:'等待处理',PENDING:'待处理',RUNNING:'处理中',LEASED:'处理中',COMPLETED:'已完成',SUCCEEDED:'已完成',FAILED:'处理失败',CANCELLED:'已取消',UNKNOWN:'结果待核对',REVIEW_REQUIRED:'需要人工审核',AWAITING_READINESS:'等待备机',RESERVED:'已预留材料',READY:'准备就绪',PRINTING:'模拟打印中',WAITING_REMOVAL:'等待取件质检',QC_PASSED:'质检通过',QC_FAILED:'需要返工',DRAFT:'等待准备',PLANNED:'等待准备',READY_TO_DISPATCH:'准备就绪',DISPATCHED:'模拟打印中',NOT_CONFIGURED:'未配置',CONFIGURED_UNVERIFIED:'待测试连接',AVAILABLE:'连接可用',UNAVAILABLE:'暂时不可用'};
const SERVICE_NAMES = {spoolman:'耗材库存',fdmMonster:'农场工作台',obico:'打印监控',karrio:'物流服务',hyperswitch:'支付测试',moonraker:'Klipper 设备',octoprint:'OctoPrint 设备'};
const KINDS = {ANALYZE_MODEL:'模型分析',SLICE_MODEL:'自动切片',CNC_REVIEW:'CNC 工艺审核',SCHEDULE:'排产计算'};
const num = value => Number.isFinite(Number(value)) ? Number(value) : 0;
const grams = value => num(value).toLocaleString('zh-CN',{maximumFractionDigits:2})+' g';
const money = value => '¥'+(num(value)/100).toFixed(2);
const duration = value => num(value) >= 3600 ? (num(value)/3600).toFixed(1)+' 小时' : Math.ceil(num(value)/60)+' 分钟';
const statusOf = value => value?.status || value?.state || 'PENDING';
const label = value => STATUS[value] || value || '待确认';
const escDefault = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function availableSpoolGrams(spool) { return Math.max(0,num(spool.remainingGrams)-num(spool.reservedGrams)); }
export function canCancelOperation(job) { return ['QUEUED','PENDING'].includes(statusOf(job)); }
export function operationModeLabel(record) { return ['SANDBOX','SIMULATED'].includes(record?.mode) || record?.simulated===true ? '模拟演练' : '制造服务处理'; }

export function createOperationsUI({icon=()=>'',escape=escDefault,render=()=>{},modal=()=>{},closeModal=()=>{},toast=()=>{},getRequest=get,prepareRequest=prepareMutation,document:dom=globalThis.document,isActive=()=>true}={}) {
  const state={tab:'jobs',data:null,services:null,loading:false,servicesLoading:false,busy:false,error:null,retry:null,spoolObservation:null,tracking:null};
  let epoch=0,pollTimer=null;
  const esc=escape,$=selector=>dom?.querySelector(selector),date=value=>value?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)):'待确认';
  const button=(action,text,{primary=false,attrs='',disabled=false}={})=>'<button type="button" class="btn '+(primary?'primary':'')+'" data-ops-action="'+action+'" '+attrs+(state.busy||disabled?' disabled':'')+'>'+text+'</button>';
  const badge=(text,extra='')=>'<span class="ops-badge '+extra+'">'+esc(text)+'</span>';
  const fields=(id,title,value='',attrs='')=>'<label class="ops-field" for="'+id+'"><span>'+title+'</span><input class="input" id="'+id+'" value="'+esc(value)+'" '+attrs+'/></label>';
  const select=(id,title,options,selected='')=>'<label class="ops-field" for="'+id+'"><span>'+title+'</span><select class="select" id="'+id+'">'+options.map(([value,text])=>'<option value="'+esc(value)+'" '+(String(value)===String(selected)?'selected':'')+'>'+esc(text)+'</option>').join('')+'</select></label>';
  const note=text=>'<p class="ops-note">'+text+'</p>';
  const empty=(title,text,action='')=>'<section class="card ops-empty"><div class="ops-empty-icon">'+icon('printer')+'</div><h3>'+title+'</h3><p>'+text+'</p>'+action+'</section>';
  const records=key=>Array.isArray(state.data?.[key])?state.data[key]:[];
  const formError='<div id="ops-form-error" class="error-text" role="alert"></div>';
  function showError(error){state.error=error;const node=$('#ops-form-error');if(node)node.textContent=error.message;render();}
  function modalBusy(value){dom?.querySelectorAll?.('[data-ops-modal] [data-ops-action]').forEach(el=>{el.disabled=value;});}
  function showForm(title,body,action,submit='保存',attrs=''){modal(title,'<div class="ops-modal" data-ops-modal>'+body+formError+'</div>','<button type="button" class="btn" data-action="close">取消</button>'+button(action,submit,{primary:true,attrs}),true);}
  function notice(){return state.error?'<div class="request-notice error" role="alert"><span>'+esc(state.error.message)+'</span>'+button('retry',state.retry?'重试原操作':'重新读取')+'</div>':'';}
  function schedulePoll(){clearTimeout(pollTimer);if(!globalThis.window||!isActive()||dom?.hidden)return;const pending=records('jobs').some(j=>['QUEUED','LEASED'].includes(statusOf(j)))||records('productions').some(p=>statusOf(p)==='PRINTING');if(pending)pollTimer=setTimeout(()=>{if(!isActive()||dom?.hidden)return;if(state.busy)schedulePoll();else load({quiet:true});},8000);}
  async function load({quiet=false}={}) {
    if(state.loading)return;
    const generation=epoch;state.loading=true;if(!quiet)render();
    try{const response=await getRequest('/merchant/operations');if(generation!==epoch)return;state.data=response.operations||response;state.error=null;if(state.tab==='services')await loadServices({quiet:true});}
    catch(error){if(generation===epoch)showError(error);}
    finally{if(generation===epoch){state.loading=false;render();schedulePoll();}}
  }
  async function loadServices({quiet=false}={}) {
    if(state.servicesLoading)return;
    const generation=epoch;state.servicesLoading=true;if(!quiet)render();
    try{const response=await getRequest('/merchant/integrations');if(generation!==epoch)return;state.services=response;state.error=null;}
    catch(error){if(generation===epoch)showError(error);}
    finally{if(generation===epoch){state.servicesLoading=false;render();}}
  }
  async function execute(task,success) {
    if(state.busy)return;
    const generation=epoch;state.busy=true;state.error=null;state.retry={task,success};modalBusy(true);render();
    try{const result=await task.execute();if(generation!==epoch)return;state.retry=null;await success(result);}
    catch(error){if(generation===epoch)showError(error);}
    finally{if(generation===epoch){state.busy=false;modalBusy(false);render();}}
  }
  async function mutate(type,payload,success=async()=>{closeModal();await load({quiet:true});toast('操作已保存。');}) {
    if(state.busy)return;
    const generation=epoch;
    try{const task=await prepareRequest('/merchant/operations/commands',{type,payload});if(generation!==epoch)return;await execute(task,success);}catch(error){showError(error);}
  }
  async function serviceMutation(path,payload,success) {
    if(state.busy)return;
    const generation=epoch;
    try{const task=await prepareRequest('/merchant/integrations/'+path,payload);if(generation!==epoch)return;await execute(task,success);}catch(error){showError(error);}
  }
  function reset(){epoch++;clearTimeout(pollTimer);Object.assign(state,{tab:'jobs',data:null,services:null,loading:false,servicesLoading:false,busy:false,error:null,retry:null,spoolObservation:null,tracking:null});}
  function summary(){const active=records('productions').filter(p=>!['QC_PASSED','CANCELLED'].includes(statusOf(p))),waiting=records('jobs').filter(j=>['QUEUED','LEASED','RUNNING'].includes(statusOf(j))),available=records('spools').filter(s=>s.mode==='SANDBOX').reduce((sum,s)=>sum+availableSpoolGrams(s),0);return '<div class="ops-summary">'+[['待处理任务',waiting.length,'模型运算'],['生产记录',active.length,'待完成或质检'],['演练可用材料',grams(available),'演示库存'],['工艺模板',records('profiles').filter(p=>p.enabled).length,'已启用']].map(([name,value,caption])=>'<div><span>'+name+'</span><strong>'+value+'</strong><small>'+caption+'</small></div>').join('')+'</div>';}
  function jobRow(job){return '<article class="ops-row"><div class="ops-row-main"><div class="ops-row-heading"><strong>'+esc(job.modelName||job.modelSnapshot?.name||job.input?.modelName||records('models').find(m=>m.id===job.modelId)?.name||KINDS[job.kind]||'模型任务')+'</strong>'+badge(label(statusOf(job)))+'</div><p>'+esc(KINDS[job.kind]||job.kind)+' · '+esc(operationModeLabel(job))+' · '+date(job.createdAt)+'</p>'+(job.error?.message?'<p class="ops-error">'+esc(job.error.message)+'</p>':'')+'</div><div class="ops-row-actions">'+button('job-details','查看结果',{attrs:'data-id="'+esc(job.id)+'"'})+(canCancelOperation(job)?button('cancel-job','取消',{attrs:'data-id="'+esc(job.id)+'"'}):'')+'</div></article>';}
  function productionRow(p){const stage=statusOf(p),title=p.modelName||p.orderSnapshot?.modelName||records('orders').find(o=>o.id===p.orderId)?.modelName||p.orderId;return '<article class="ops-row"><div class="ops-row-main"><div class="ops-row-heading"><strong>'+esc(title||'生产记录')+'</strong>'+badge(label(stage))+'</div><p>'+esc(p.orderId)+' · '+esc(operationModeLabel(p))+'</p><small>预留材料 '+grams(p.reservedGrams??p.estimatedMaterialGrams??p.estimate?.materialGrams)+' · '+esc(p.deviceName||p.deviceId||'设备待确认')+'</small></div><div class="ops-row-actions">'+button('production-details','查看与处理',{attrs:'data-id="'+esc(p.id)+'"'})+'</div></article>';}
  function scheduleHTML(){const schedule=state.data?.schedule,entries=Array.isArray(schedule)?schedule:schedule?.schedule||schedule?.entries||schedule?.assignments||[];return '<section class="card ops-schedule"><div class="ops-section-heading"><div><h2>预计生产安排</h2><p>按已知工时安排设备，供商家核对。</p></div>'+'<div class="ops-row-actions">'+button('schedule','快速排期',{disabled:!records('productions').length})+button('queue-schedule','优化排期',{disabled:!records('productions').length})+'</div>'+'</div>'+(entries.length?'<div class="ops-schedule-list">'+entries.slice(0,20).map(item=>'<div><strong>'+esc(item.orderId||item.productionId||item.jobId||'生产任务')+'</strong><span>'+esc(item.deviceId||'待分配设备')+'</span><span>'+date(item.startAt||item.start)+' — '+date(item.endAt||item.end)+'</span></div>').join('')+'</div>':note('建立生产记录后，可生成排期建议。尚未纳入运输时效，不能直接当作客户收货承诺。'))+'</section>';}
  function jobsPage(){return (state.data?.workerReadiness?'<div class="ops-worker-state">'+badge(state.data.workerReadiness.configured?'运算授权已配置 · 尚未验证在线':'制造服务尚未配置')+note(state.data.workerReadiness.configured?'实际任务由已授权制造服务领取。配置存在不代表服务正在运行。':'可先进行模拟演练。实际分析与切片任务会保持排队，直到管理员连接制造服务。')+'</div>':'')+'<div class="ops-section-heading"><div><h2>模型运算</h2><p>分析与切片结果绑定模型和工艺版本。</p></div>'+button('new-job','创建模型任务 '+icon('plus'),{primary:true})+'</div>'+(records('jobs').length?'<div class="card ops-list">'+[...records('jobs')].reverse().slice(0,25).map(jobRow).join('')+'</div>':empty('从检查模型开始','选择已上传的模型，安排分析或切片。真实运算任务由制造服务领取。'))+'<div class="ops-section-heading"><div><h2>生产记录</h2><p>记录材料预留、开工、实耗和取件质检。</p></div>'+button('new-production','建立生产记录 '+icon('plus'),{primary:true})+'</div>'+(records('productions').length?'<div class="card ops-list">'+[...records('productions')].reverse().slice(0,25).map(productionRow).join('')+'</div>':empty('让生产有迹可查','已有订单和有效切片结果后，创建记录并预留材料。当前生产控制为模拟演练。'))+scheduleHTML();}
  function inventoryPage(){return '<div class="ops-section-heading"><div><h2>材料库存</h2><p>可用量 = 账面余量 − 已预留。采购成本仅商家可见。</p></div>'+button('new-spool','添加材料 '+icon('plus'),{primary:true})+'</div>'+(records('spools').length?'<div class="ops-grid">'+records('spools').map(s=>'<article class="card ops-inventory-card"><div class="ops-row-heading"><h3>'+esc(s.name)+'</h3>'+badge(s.mode==='LIVE_INVENTORY'?'实际库存登记':'演示库存')+'</div><p>'+esc(MATERIALS[s.material]||s.material)+' · v'+num(s.revision)+'</p><div class="ops-stock"><strong>'+grams(availableSpoolGrams(s))+'</strong><span>可用</span></div><div class="ops-stock-bar" aria-hidden="true"><span style="width:'+Math.min(100,num(s.remainingGrams)?availableSpoolGrams(s)/num(s.remainingGrams)*100:0)+'%"></span></div><dl class="ops-facts"><div><dt>账面余量</dt><dd>'+grams(s.remainingGrams)+'</dd></div><div><dt>生产预留</dt><dd>'+grams(s.reservedGrams)+'</dd></div><div><dt>采购单价</dt><dd>'+(s.costConfigured===false||s.costCentsPerKg==null?'采购价待填写':money(s.costCentsPerKg)+' / kg')+'</dd></div></dl>'+(s.source==='SPOOLMAN'?note('来源：已连接耗材服务 · 库存请在原系统维护后刷新')+button('edit-spool-cost',s.costConfigured===false?'填写采购价':'更新采购价',{attrs:'data-id="'+esc(s.id)+'"'}):button('edit-spool','更新库存',{attrs:'data-id="'+esc(s.id)+'"'}))+'</article>').join('')+'</div>':empty('添加第一份材料库存','登记当前余量和采购价格，生产任务将按预估用量预留。',button('new-spool','添加材料',{primary:true})))+note('实际库存与演示库存分开记录。连接外部耗材服务后，可在“服务连接”查看最新观察值，再核对本地账面。');}
  function profilesPage(){return '<div class="ops-section-heading"><div><h2>工艺模板</h2><p>客户只需提交模型和用途，由你管理经过验证的工艺。</p></div>'+button('new-profile','添加工艺模板 '+icon('plus'),{primary:true})+'</div>'+(records('profiles').length?'<div class="ops-grid">'+records('profiles').map(p=>'<article class="card ops-profile-card"><div class="ops-row-heading"><h3>'+esc(p.name)+'</h3>'+badge(p.enabled?'已启用':'已停用')+'</div><p>'+esc(p.process)+' · '+esc(MATERIALS[p.material]||p.material)+' · v'+num(p.revision)+'</p><dl class="ops-facts"><div><dt>对应设备</dt><dd>'+esc(p.deviceName||p.deviceId)+'</dd></div><div><dt>配置标识</dt><dd>'+esc(p.localProfileId)+'</dd></div><div><dt>制造方式</dt><dd>'+esc(p.engine)+'</dd></div><div><dt>现场认证</dt><dd>待设备与材料实测</dd></div></dl>'+button('edit-profile','编辑模板',{attrs:'data-id="'+esc(p.id)+'"'})+'</article>').join('')+'</div>':empty('先保存你熟悉的工艺','关联设备、材料和本地配置。更改模板会产生新版本，已有结果保留原版本。',button('new-profile','添加工艺模板',{primary:true})))+note('登记模板不等于工艺认证。真实切片需要制造服务内已安装、内容相符的配置文件；CNC 模板继续走人工工艺审核。');}
  function servicesPage(){const services=state.services?.services||[];return '<div class="ops-section-heading"><div><h2>服务连接</h2><p>检查已配置的服务。连接可用与获准执行是不同状态。</p></div>'+button('refresh-services',state.servicesLoading?'正在读取…':'刷新连接',{disabled:state.servicesLoading})+'</div>'+(state.servicesLoading&&!state.services?empty('正在读取连接状态','稍等片刻，服务配置只从服务器读取。'):!state.services?empty('暂未读取服务连接','可重新读取，或先完成材料与工艺登记。',button('refresh-services','重新读取')):'<div class="ops-grid">'+services.map(s=>'<article class="card ops-service-card"><div class="ops-row-heading"><h3>'+esc(SERVICE_NAMES[s.id]||s.label||s.id)+'</h3>'+badge(label(s.state))+'</div><p>'+esc(s.message||'请先在服务端完成连接配置。')+'</p><small>'+esc(s.mode==='TEST_ONLY'?'支付测试环境':s.mode==='CONTROL_GATED'?'设备控制尚需授权与现场验证':'只读状态与信息')+'</small><div class="ops-row-actions">'+button('probe-service','测试连接',{attrs:'data-service="'+esc(s.id)+'"',disabled:!s.configured})+(s.id==='spoolman'?button('sync-spools','同步库存观察',{disabled:!s.configured}):s.id==='karrio'?button('tracking-prompt','查询物流',{disabled:!s.configured}):'')+'</div></article>').join('')+'</div>')+(state.spoolObservation?spoolObservationHTML():'')+(state.tracking?trackingHTML():'')+note('服务地址和密钥由管理员在服务器配置，不保存在浏览器。物流签收后仍需客户确认验收，才进入平台结算流程。');}
  function spoolObservationHTML(){const data=state.spoolObservation;return '<section class="card ops-observation"><div class="ops-section-heading"><div><h2>外部库存观察</h2><p>'+date(data.observedAt)+' · '+(data.spools||[]).length+' 卷</p></div>'+badge('只读快照')+'</div>'+((data.spools||[]).length?'<div class="ops-schedule-list">'+data.spools.slice(0,50).map(s=>'<div><strong>'+esc(s.name||s.externalId)+'</strong><span>'+esc(s.material)+'</span><span>'+grams(s.remainingGrams)+'</span></div>').join('')+'</div>':note('本次未返回耗材记录。'))+note(data.truncated?'结果已截断；请到耗材服务核对完整库存。':'已同步为外部只读库存，不覆盖手工库存或生产预留。采购价未提供时需要单独填写。')+'</section>';}
  function trackingHTML(){const data=state.tracking;return '<section class="card ops-observation"><div class="ops-section-heading"><div><h2>物流观察</h2><p>读取时间 '+date(data.observedAt)+'</p></div>'+badge(data.delivered?'物流显示已签收':data.status||'状态待确认')+'</div><ol class="ops-tracking">'+(data.events||[]).slice(0,20).map(e=>'<li><strong>'+esc(e.description||e.message||e.status||'物流事件')+'</strong><span>'+esc(e.location||'')+' · '+esc(e.timestamp||e.time||e.at||'')+'</span></li>').join('')+'</ol>'+note('这是承运商事件记录，不代表客户已验收，也不会触发放款。')+'</section>';}
  function page(){return '<div class="ops-center"><div class="page-intro merchant-intro"><div><div class="eyebrow">PRODUCTION STUDIO</div><h1>生产中心</h1><p>从模型检查到取件质检，掌握每一步。</p></div><div class="intro-actions">'+button('refresh',icon('rotate')+'刷新状态',{disabled:state.loading})+'</div></div><div class="ops-sandbox-note">'+icon('shield')+'<span>生产与款项仍为沙盒。真实模型运算需连接制造服务；设备开打需完成独立验证。</span></div>'+notice()+(state.loading&&!state.data?'<div class="card ops-empty" role="status"><h3>正在读取生产工作台…</h3><p>任务、材料和工艺记录由服务器保存。</p></div>':!state.data?empty('生产工作台尚未加载','请先读取当前账号的生产记录。',button('refresh','读取工作台',{primary:true})):summary()+'<div class="ops-tabs" role="tablist" aria-label="生产工作台">'+TABS.map(([id,text])=>'<button type="button" id="ops-tab-'+id+'" role="tab" aria-controls="ops-panel" aria-selected="'+(state.tab===id)+'" class="'+(state.tab===id?'active':'')+'" data-ops-action="tab" data-tab="'+id+'">'+text+'</button>').join('')+'</div><section id="ops-panel" role="tabpanel" aria-labelledby="ops-tab-'+state.tab+'">'+(state.tab==='inventory'?inventoryPage():state.tab==='profiles'?profilesPage():state.tab==='services'?servicesPage():jobsPage())+'</section>')+'</div>';}
  function editSpool(id){const s=records('spools').find(v=>v.id===id)||{name:'',material:'PLA',remainingGrams:1000,costCentsPerKg:0,mode:'SANDBOX',revision:0};showForm(id?'更新材料库存':'添加材料库存','<form id="ops-spool-form" data-id="'+esc(s.id||'')+'" data-revision="'+num(s.revision)+'">'+fields('ops-spool-name','材料名称',s.name,'required maxlength="80" placeholder="例如：白色 PLA · 第 01 卷"')+'<div class="ops-form-grid">'+select('ops-spool-material','材料',Object.entries(MATERIALS),s.material)+select('ops-spool-mode','库存用途',[['SANDBOX','演示库存 · 用于模拟生产'],['LIVE_INVENTORY','实际库存登记 · 不授权打印']],s.mode)+fields('ops-spool-grams','当前账面余量 / g',s.remainingGrams,'type="number" min="0" max="1000000" step="0.01" required')+fields('ops-spool-cost','采购单价 / 元每千克',(num(s.costCentsPerKg)/100).toFixed(2),'type="number" min="0" max="100000" step="0.01" required')+'</div>'+note('已预留 '+grams(s.reservedGrams)+'。更新后余量不得小于仍在生产中的预留。采购价只影响新记录。')+'</form>','save-spool');if(id){['ops-spool-material','ops-spool-mode'].forEach(key=>{const el=$('#'+key);if(el)el.disabled=true;});}}
  function editSpoolCost(id){const s=records('spools').find(v=>v.id===id);if(!s)return;showForm('填写材料采购价','<form id="ops-spool-cost-form" data-id="'+esc(s.id)+'" data-revision="'+num(s.revision)+'"><p>'+esc(s.name)+'</p>'+fields('ops-spool-unit-cost','采购单价 / 元每千克',s.costCentsPerKg==null?'':(num(s.costCentsPerKg)/100).toFixed(2),'type="number" min="0" max="100000" step="0.01" required')+note('只更新成本，不修改外部库存余量。你填写的采购价将在后续同步中保留。')+'</form>','save-spool-cost');}
  function editProfile(id){const devices=records('devices'),p=records('profiles').find(v=>v.id===id)||{name:'',localProfileId:'',engine:'PrusaSlicer',process:'FDM',material:'PLA',quality:'standard',deviceId:devices[0]?.id||'',farmId:devices[0]?.farmId||devices[0]?.farm||'f1',enabled:true,revision:0};showForm(id?'更新工艺模板':'添加工艺模板','<form id="ops-profile-form" data-id="'+esc(p.id||'')+'" data-revision="'+num(p.revision)+'" data-farm="'+esc(p.farmId)+'">'+fields('ops-profile-name','模板名称',p.name,'required maxlength="80" placeholder="例如：PLA 功能件 · 标准工艺"')+'<div class="ops-form-grid">'+select('ops-profile-engine','制造方式',[['PrusaSlicer','FDM 自动切片'],['FreeCAD','CNC 人工工艺审核']],p.engine)+select('ops-profile-material','材料',p.engine==='FreeCAD'?[['CNC','CNC 材料']]:[['PLA','PLA'],['PETG','PETG'],['ABS','ABS']],p.material)+select('ops-profile-device','关联设备',devices.length?devices.map(d=>[d.id,(d.name||d.id)+(d.source==='demo'?' · 演示设备':' · 已登记')]):[['','请先添加设备']],p.deviceId)+select('ops-profile-farm','计价产线',[['f1','工场一 · 演示计价'],['f2','工场二 · 演示计价'],['f3','工场三 · 演示计价']],p.farmId)+select('ops-profile-quality','工艺档位',[['standard','标准'],['fine','精细']],p.quality||'standard')+fields('ops-profile-local','本地配置标识',p.localProfileId,'required maxlength="80" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,79}" placeholder="例如：pla-standard"')+'</div><details class="ops-advanced"><summary>配置文件校验</summary>'+fields('ops-profile-hash','配置 SHA-256（选填）',p.expectedProfileSha256||'','maxlength="64" pattern="[a-fA-F0-9]{64}" placeholder="管理员提供的配置文件校验值"')+'</details><label class="check-line"><input id="ops-profile-enabled" type="checkbox" '+(p.enabled?'checked':'')+'/>启用此模板</label>'+note('本地配置标识必须与制造服务中已安装的配置相符。模板只记录你的选择，实际设备和工艺仍需试打验证。')+'</form>','save-profile');}
  function newJob(){const models=records('models').filter(m=>['stl','3mf'].includes(m.format)),profiles=records('profiles').filter(p=>p.enabled&&p.process==='FDM');showForm('安排模型分析与切片','<form id="ops-job-form">'+select('ops-job-model','选择模型',models.length?models.map(m=>[m.id,m.name+(m.isSample?' · 示例文件':'')]):[['','请先上传模型']])+'<div class="ops-form-grid">'+select('ops-job-kind','任务类型',[['ANALYZE_MODEL','检查模型几何'],['SLICE_MODEL','按商家工艺切片']])+select('ops-job-mode','处理方式',[['WORKER','实际运算 · 等待制造服务'],['SANDBOX','模拟演练 · 不执行真实切片']])+select('ops-job-unit','模型尺寸单位',[['mm','毫米 mm'],['inch','英寸 inch']])+fields('ops-job-qty','数量',1,'type="number" min="1" max="50" step="1" required')+'</div><div id="ops-job-profile-field" hidden>'+select('ops-job-profile','切片工艺',profiles.length?profiles.map(p=>[p.id,p.name+' · v'+p.revision]):[['','请先添加 FDM 工艺模板']])+'</div>'+note('真实任务将排队等待制造服务。切片结果会绑定文件、数量、单位和工艺版本；不会更改已付款订单，也不会启动打印机。')+'</form>','save-job','创建任务');}
  function productionChoices(order){
    const jobs = records('jobs').filter(job => {
      if (!order || order.capabilityUnverified || job.kind !== 'SLICE_MODEL' || statusOf(job) !== 'COMPLETED') return false;
      if (order.frozenSliceJobId && job.id !== order.frozenSliceJobId) return false;
      if (order.modelHash && order.modelHash !== job.modelHash) return false;
      if (order.modelVersion != null && order.modelVersion !== (job.modelVersion ?? 1)) return false;
      const config = job.configSnapshot;
      if (!config || order.allowedDeviceIds?.length && !order.allowedDeviceIds.includes(config.deviceId)) return false;
      return job.modelId === order.modelId && job.quantity === (order.quantity || order.qty) &&
        job.unit === (order.unit || 'mm') && config.material === order.material && config.farmId === order.farmId &&
        (config.quality || 'standard') === (order.quality || 'standard') &&
        records('profiles').some(profile => profile.id === job.profileId && profile.revision === job.profileRevision && profile.enabled);
    });
    const spools=records('spools').filter(s=>s.mode==='SANDBOX'&&(!order||s.material===order.material));
    return {jobs,spools};
  }
  function productionSelectOptions(order){const {jobs,spools}=productionChoices(order);return {
    jobs:jobs.length?jobs.map(j=>[j.id,(records('models').find(m=>m.id===j.modelId)?.name||j.modelId)+' · '+j.quantity+' 件 · '+operationModeLabel(j)]):[['',order?.capabilityUnverified?'旧订单的设备范围需与客户重新确认':'此订单还没有匹配的有效切片结果']],
    spools:spools.length?spools.map(s=>[s.id,s.name+' · 可用 '+grams(availableSpoolGrams(s))]):[['','请先添加同材料的演示库存']]
  };}
  function newProduction(){const orders=records('orders').filter(o=>o.paymentState==='SIMULATED_FROZEN'&&!['WAITING_REMOVAL','QC_PASSED','QC_FAILED','CANCELLED'].includes(o.productionState)&&!records('productions').some(p=>p.orderId===o.id)),options=productionSelectOptions(orders[0]);showForm('建立模拟生产记录','<form id="ops-production-form">'+select('ops-production-order','已确认订单',orders.length?orders.map(o=>[o.id,(o.modelName||o.id)+' · '+(o.qty||o.quantity||1)+' 件']):[['','暂无可建立生产台账的演示订单']])+'<div id="ops-adopt-existing" '+(orders[0]?.productionState==='PRINTING'?'':'hidden')+'><label class="check-line"><input type="checkbox" id="ops-adopt-confirm" '+(orders[0]?.productionState==='PRINTING'?'required':'')+'/>把现有模拟打印迁入生产台账，并重新确认备机</label></div>'+select('ops-production-slice','有效切片结果',options.jobs)+select('ops-production-spool','预留材料',options.spools)+note('仅显示模型、数量、单位、材料和工艺匹配的切片结果。创建记录会预留演示材料，后续取消可释放；此处只建立模拟生产记录。')+'</form>','save-production','建立记录并预留材料');}

  function details(items){return '<dl class="ops-facts ops-detail-facts">'+items.filter(([,value])=>value!==undefined&&value!==null&&value!=='').map(([key,value])=>'<div><dt>'+esc(key)+'</dt><dd>'+esc(value)+'</dd></div>').join('')+'</dl>';}
  function jobDetails(id){const j=records('jobs').find(v=>v.id===id);if(!j)return;const r=j.result||j.output||{},geometry=r.geometry||r.analysis||r,metrics=r.metrics||r.estimate||r;modal('任务详情','<div class="ops-modal">'+details([['任务',KINDS[j.kind]||j.kind],['状态',label(statusOf(j))],['处理方式',operationModeLabel(j)],['模型',j.modelName||records('models').find(m=>m.id===j.modelId)?.name||j.modelId],['任务版本',j.profileRevision||j.profileVersion],['数量',j.quantity?j.quantity+' 件':undefined],['单位',j.unit],['文件校验',j.modelHash||j.modelSha256||j.input?.modelHash],['三维尺寸',Array.isArray(geometry.dimensionsMm)?geometry.dimensionsMm.join(' × ')+' mm':undefined],['闭合性',typeof geometry.watertight==='boolean'?(geometry.watertight?'闭合':'未闭合'):typeof geometry.closed==='boolean'?(geometry.closed?'闭合':'未闭合'):undefined],['耗材估算',metrics.materialGrams!==undefined?grams(metrics.materialGrams):metrics.filamentGrams!==undefined?grams(metrics.filamentGrams):undefined],['打印估时',metrics.durationSeconds!==undefined?duration(metrics.durationSeconds):undefined],['运算程序',r.engineVersion||r.engine||r.analyzer||r.slicerVersion],['完成时间',j.completedAt?date(j.completedAt):undefined]])+(j.error?.message?'<p class="ops-error">'+esc(j.error.message)+'</p>':'')+((r.warnings||geometry.warnings||[]).length?'<ul class="ops-notes">'+(r.warnings||geometry.warnings||[]).map(w=>'<li>'+esc(typeof w==='string'?w:w.message||w.code)+'</li>').join('')+'</ul>':'')+note('模型检查或切片估算通过，不等于强度、表面质量或设备现场条件已验收。')+'</div>','<button type="button" class="btn" data-action="close">关闭</button>',true);}
  function productionDetails(id){const p=records('productions').find(v=>v.id===id);if(!p)return;const stage=statusOf(p),actions=[];
    if(['AWAITING_READINESS','RESERVED','DRAFT','PLANNED','READY','READY_TO_DISPATCH'].includes(stage))actions.push(button('readiness-prompt','确认备机',{attrs:'data-id="'+esc(id)+'"'}));
    if(['READY','READY_TO_DISPATCH'].includes(stage))actions.push(button('dispatch','开始模拟生产',{primary:true,attrs:'data-id="'+esc(id)+'"'}));
    if(['PRINTING','DISPATCHED','RUNNING'].includes(stage))actions.push(button('finish-prompt','登记完工实耗',{primary:true,attrs:'data-id="'+esc(id)+'"'}));
    if(['WAITING_REMOVAL'].includes(stage))actions.push(button('qc-prompt','取件与质检',{primary:true,attrs:'data-id="'+esc(id)+'"'}));
    if(['AWAITING_READINESS','RESERVED','DRAFT','PLANNED','READY','READY_TO_DISPATCH'].includes(stage))actions.push(button('cancel-production','取消并释放材料',{attrs:'data-id="'+esc(id)+'"'}));
    modal('生产记录 · 模拟','<div class="ops-modal">'+details([['订单',p.orderId],['状态',label(stage)],['设备',p.deviceName||p.deviceId],['材料预留',grams(p.reservedGrams??p.estimatedMaterialGrams??p.estimate?.materialGrams)],['预计机时',p.estimatedDurationSeconds!==undefined?duration(p.estimatedDurationSeconds):undefined],['实际耗材',p.actualMaterialGrams!==undefined?grams(p.actualMaterialGrams):p.actuals?.materialGrams!==undefined?grams(p.actuals.materialGrams):undefined],['实际机时',p.actualDurationSeconds!==undefined?duration(p.actualDurationSeconds):p.actuals?.durationSeconds!==undefined?duration(p.actuals.durationSeconds):undefined],['实际制造成本',p.actualCostCents!==undefined?money(p.actualCostCents):p.actuals?.actualCostCents!==undefined?money(p.actuals.actualCostCents):undefined],['模拟毛利',p.actualProfitCents!==undefined?money(p.actualProfitCents):p.actuals?.profitCents!=null?money(p.actuals.profitCents):undefined]])+note('实耗用于核对材料、机时与成本。取件质检与客户验收分别记录；这里不会控制真实设备或释放真实款项。')+formError+'</div>','<button type="button" class="btn" data-action="close">关闭</button>'+actions.join(''),true);}
  function readinessPrompt(id){showForm('核对模拟开工条件','<form id="ops-readiness-form"><div class="ops-checks">'+[['bed','已取走上一次部件并清理平台'],['material-check','已核对材料与剩余用量'],['device','设备无报警且无其他生产任务']].map(([key,text])=>'<label class="check-line"><input type="checkbox" id="ops-ready-'+key+'" required/>'+text+'</label>').join('')+'</div>'+select('ops-ready-material','当前装载材料',Object.entries(MATERIALS),records('productions').find(p=>p.id===id)?.material||'PLA')+note('以上记录仅用于本次模拟流程，真实机器需要独立的现场检查与控制授权。')+'</form>','save-readiness','保存备机记录','data-id="'+esc(id)+'"');}
  function finishPrompt(id){const p=records('productions').find(p=>p.id===id);showForm('登记模拟完工实耗','<form id="ops-finish-form"><div class="ops-form-grid">'+fields('ops-finish-grams','实际材料消耗 / g',p?.estimatedMaterialGrams??p?.reservedGrams??'','type="number" min="0" max="1000000" step="0.01" required')+fields('ops-finish-minutes','实际打印时间 / 分钟',p?.estimatedDurationSeconds?num(p.estimatedDurationSeconds)/60:'','type="number" min="0.01" max="525600" step="0.01" required')+'</div>'+note('请输入包含支撑和废料的实际用量。登记后更新账面库存，并进入取件与质检。')+'</form>','save-finish','保存实耗','data-id="'+esc(id)+'"');}
  function qcPrompt(id){showForm('取件与质检','<form id="ops-qc-form"><div class="ops-checks"><label class="check-line"><input type="checkbox" id="ops-qc-removed" required/>已取出部件</label><label class="check-line"><input type="checkbox" id="ops-qc-clear" required/>已清理打印平台</label></div>'+select('ops-qc-passed','质检结果',[['true','通过 · 可继续履约'],['false','未通过 · 需要返工']])+fields('ops-qc-note','检查说明','','maxlength="500" placeholder="记录尺寸、表面与异常情况"')+note('质检通过不会直接确认客户收货，也不会自动结算款项。')+'</form>','save-qc','保存质检结果','data-id="'+esc(id)+'"');}
  function trackingPrompt(){showForm('查询物流轨迹','<form id="ops-tracking-form">'+fields('ops-tracking-carrier','承运商标识','','required maxlength="80" placeholder="使用已配置承运商标识"')+fields('ops-tracking-number','物流单号','','required maxlength="120" autocomplete="off"')+note('只查询指定运单。物流记录不会自动标记客户验收或放款。')+'</form>','save-tracking','查询物流');}
  const value=id=>$('[id="'+id+'"]')?.value??$('#'+id)?.value??'';
  const checked=id=>$('#'+id)?.checked===true;
  const valid=id=>$('#'+id)?.reportValidity?.()===true;
  async function saveSpool(){const form=$('#ops-spool-form');if(!valid('ops-spool-form'))return;await mutate('save-spool',{...(form.dataset.id?{id:form.dataset.id}:{}),expectedRevision:Number(form.dataset.revision),name:value('ops-spool-name').trim(),material:value('ops-spool-material'),mode:value('ops-spool-mode'),remainingGrams:Number(value('ops-spool-grams')),costCentsPerKg:Math.round(Number(value('ops-spool-cost'))*100)});}
  async function saveSpoolCost(){if(!valid('ops-spool-cost-form'))return;const form=$('#ops-spool-cost-form');await mutate('set-spool-cost',{id:form.dataset.id,expectedRevision:Number(form.dataset.revision),costCentsPerKg:Math.round(Number(value('ops-spool-unit-cost'))*100)});}
  async function saveProfile(){const form=$('#ops-profile-form');if(!valid('ops-profile-form'))return;const deviceId=value('ops-profile-device'),device=records('devices').find(d=>d.id===deviceId);if(!deviceId){showError({message:'请先登记设备，再关联工艺模板。'});return;}const hash=value('ops-profile-hash').trim().toLowerCase(),engine=value('ops-profile-engine');await mutate('save-profile',{...(form.dataset.id?{id:form.dataset.id}:{}),expectedRevision:Number(form.dataset.revision),name:value('ops-profile-name').trim(),localProfileId:value('ops-profile-local').trim(),engine,process:engine==='FreeCAD'?'CNC':'FDM',material:value('ops-profile-material'),deviceId,farmId:value('ops-profile-farm'),quality:value('ops-profile-quality'),enabled:checked('ops-profile-enabled'),...(hash?{expectedProfileSha256:hash}:{})});}
  async function saveJob(){if(!valid('ops-job-form'))return;const kind=value('ops-job-kind'),mode=value('ops-job-mode'),modelId=value('ops-job-model'),profileId=value('ops-job-profile');if(mode==='WORKER'&&records('models').find(m=>m.id===modelId)?.isSample){showError({message:'示例模型没有实际文件。请上传模型，或明确选择模拟演练。'});return;}if(!modelId||kind==='SLICE_MODEL'&&!profileId){showError({message:'请选择模型；切片任务还需要已启用的工艺模板。'});return;}await mutate('queue-job',{kind,modelId,quantity:Number(value('ops-job-qty')),unit:value('ops-job-unit'),mode,...(kind==='SLICE_MODEL'?{profileId}:{}),...(mode==='SANDBOX'?{demoAcknowledged:true}:{})});}
  async function saveProduction(){if(!valid('ops-production-form'))return;const orderId=value('ops-production-order'),sliceJobId=value('ops-production-slice'),spoolId=value('ops-production-spool');if(!orderId||!sliceJobId||!spoolId){showError({message:'需要已确认订单、有效切片结果和演示库存。'});return;}await mutate('create-production',{orderId,sliceJobId,spoolId,demoAcknowledged:true,...(records('orders').find(o=>o.id===orderId)?.productionState==='PRINTING'&&checked('ops-adopt-confirm')?{adoptExistingSimulation:true}:{})});}
  async function handleAction(action,target){if(!isActive()||state.busy)return;
    if(action==='tab'){state.tab=TABS.some(([id])=>id===target.dataset.tab)?target.dataset.tab:'jobs';state.error=null;render();if(state.tab==='services'&&!state.services)await loadServices();return;}
    if(action==='refresh')return load();if(action==='retry')return state.retry?execute(state.retry.task,state.retry.success):state.tab==='services'?loadServices():load();
    if(action==='edit-spool-cost')return editSpoolCost(target.dataset.id);if(action==='save-spool-cost')return saveSpoolCost();if(action==='new-spool'||action==='edit-spool')return editSpool(target.dataset.id);if(action==='save-spool')return saveSpool();
    if(action==='new-profile'||action==='edit-profile')return editProfile(target.dataset.id);if(action==='save-profile')return saveProfile();
    if(action==='new-job')return newJob();if(action==='save-job')return saveJob();if(action==='job-details')return jobDetails(target.dataset.id);
    if(action==='cancel-job')return mutate('cancel-job',{jobId:target.dataset.id});
    if(action==='new-production')return newProduction();if(action==='save-production')return saveProduction();if(action==='production-details')return productionDetails(target.dataset.id);
    if(action==='readiness-prompt')return readinessPrompt(target.dataset.id);if(action==='save-readiness'){if(!valid('ops-readiness-form'))return;return mutate('readiness',{productionId:target.dataset.id,bedClear:checked('ops-ready-bed'),materialReady:checked('ops-ready-material-check'),deviceClear:checked('ops-ready-device'),loadedMaterial:value('ops-ready-material'),demoAcknowledged:true});}
    if(action==='dispatch')return mutate('dispatch-production',{productionId:target.dataset.id,demoAcknowledged:true});
    if(action==='finish-prompt')return finishPrompt(target.dataset.id);if(action==='save-finish'){if(!valid('ops-finish-form'))return;return mutate('finish-production',{productionId:target.dataset.id,actualMaterialGrams:Number(value('ops-finish-grams')),actualDurationSeconds:Math.round(Number(value('ops-finish-minutes'))*60),demoAcknowledged:true});}
    if(action==='qc-prompt')return qcPrompt(target.dataset.id);if(action==='save-qc'){if(!valid('ops-qc-form'))return;return mutate('qc-production',{productionId:target.dataset.id,partRemoved:checked('ops-qc-removed'),bedClear:checked('ops-qc-clear'),passed:value('ops-qc-passed')==='true',note:value('ops-qc-note').trim(),demoAcknowledged:true});}
    if(action==='cancel-production')return mutate('cancel-production',{productionId:target.dataset.id,demoAcknowledged:true});
    if(action==='schedule')return mutate('schedule',{});if(action==='queue-schedule')return mutate('queue-job',{kind:'SCHEDULE',mode:'WORKER'});if(action==='refresh-services')return loadServices();
    if(action==='probe-service')return serviceMutation('probe',{service:target.dataset.service},async result=>{const service=state.services?.services?.find(s=>s.id===target.dataset.service);if(service){service.state=result.state;service.message=result.message;service.checkedAt=result.checkedAt;}toast(result.state==='AVAILABLE'?'已读取服务响应，执行权限仍需单独验证。':'连接未通过，请检查服务器配置。');});
    if(action==='sync-spools')return serviceMutation('sync-spools',{},async result=>{state.spoolObservation=result;if(result.operations)state.data=result.operations;toast('已同步外部库存观察，请核对采购价。');});
    if(action==='tracking-prompt')return trackingPrompt();if(action==='save-tracking'){if(!valid('ops-tracking-form'))return;return serviceMutation('tracking',{carrier:value('ops-tracking-carrier').trim(),trackingNumber:value('ops-tracking-number').trim()},async result=>{state.tracking=result;closeModal();toast('已读取物流观察记录。');});}
  }
  dom?.addEventListener('click',async event=>{const target=event.target.closest?.('[data-ops-action]');if(!target)return;event.preventDefault();await handleAction(target.dataset.opsAction,target);});
  dom?.addEventListener('change',event=>{if(event.target.id==='ops-production-order'){const isPrinting=records('orders').find(o=>o.id===event.target.value)?.productionState==='PRINTING',area=$('#ops-adopt-existing'),confirm=$('#ops-adopt-confirm');if(area)area.hidden=!isPrinting;if(confirm){confirm.required=isPrinting;confirm.checked=false;}const options=productionSelectOptions(records('orders').find(o=>o.id===event.target.value));[['ops-production-slice',options.jobs],['ops-production-spool',options.spools]].forEach(([id,values])=>{const node=$('#'+id);if(node)node.innerHTML=values.map(([v,text])=>'<option value="'+esc(v)+'">'+esc(text)+'</option>').join('');});}if(event.target.id==='ops-job-kind'){const field=$('#ops-job-profile-field');if(field)field.hidden=event.target.value!=='SLICE_MODEL';}if(event.target.id==='ops-profile-engine'){const material=$('#ops-profile-material');if(material){const choices=event.target.value==='FreeCAD'?[['CNC','CNC 材料']]:[['PLA','PLA'],['PETG','PETG'],['ABS','ABS']];material.innerHTML=choices.map(([id,name])=>'<option value="'+id+'">'+name+'</option>').join('');}}});
  dom?.addEventListener('submit',event=>{const actions={'ops-spool-form':saveSpool,'ops-spool-cost-form':saveSpoolCost,'ops-profile-form':saveProfile,'ops-job-form':saveJob,'ops-production-form':saveProduction};if(event.target.id?.startsWith('ops-'))event.preventDefault();if(!state.busy&&actions[event.target.id])actions[event.target.id]();});
  dom?.addEventListener('keydown',event=>{if(event.target.closest?.('.ops-tabs')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const index=TABS.findIndex(([id])=>id===state.tab),next=event.key==='Home'?0:event.key==='End'?TABS.length-1:(index+(event.key==='ArrowRight'?1:-1)+TABS.length)%TABS.length;handleAction('tab',{dataset:{tab:TABS[next][0]}});$('#ops-tab-'+TABS[next][0])?.focus();}});
  dom?.addEventListener('visibilitychange',()=>{if(dom.hidden)clearTimeout(pollTimer);else schedulePoll();});
  globalThis.window?.addEventListener?.('pagehide',()=>clearTimeout(pollTimer));
  return {state,load,loadServices,reset,page,handleAction};
}
